#!/usr/bin/env node
'use strict';
const fs = require('fs');
const path = require('path');

function usage() {
  return 'Usage: node resolve.js --input catalog.json --out lock.json\n' +
    'Resolve a catalog offline and write a deterministic lock file.\n';
}
function fail(message, code) { process.stderr.write('resolve: ' + message + '\n'); process.exitCode = code; }
function exact(o, keys, where) {
  if (!o || typeof o !== 'object' || Array.isArray(o)) throw Error(where + ' must be an object');
  const got = Object.keys(o).sort(), want = keys.slice().sort();
  if (got.length !== want.length || got.some((x,i)=>x !== want[i])) throw Error(where + ' has invalid fields');
}
function name(x, where) {
  if (typeof x !== 'string' || x.length === 0) throw Error(where + ' must be a nonempty string');
  return x;
}
function int(x, where) {
  if (!Number.isInteger(x) || x < 1 || x > 1000) throw Error(where + ' must be an integer from 1 through 1000');
  return x;
}
function range(o, where) {
  exact(o, ['name','min','max'], where);
  const n = name(o.name, where + '.name'), lo = int(o.min, where + '.min'), hi = int(o.max, where + '.max');
  if (lo > hi) throw Error(where + ' has min greater than max');
  return {name:n,min:lo,max:hi};
}
function validate(raw) {
  exact(raw, ['packages','roots'], 'top level');
  if (!Array.isArray(raw.packages) || !Array.isArray(raw.roots)) throw Error('packages and roots must be arrays');
  const packages = new Map();
  raw.packages.forEach((p, pi) => {
    exact(p, ['name','versions'], 'packages['+pi+']');
    const n = name(p.name, 'packages['+pi+'].name');
    if (packages.has(n)) throw Error('duplicate package name: ' + n);
    if (!Array.isArray(p.versions)) throw Error('packages['+pi+'].versions must be an array');
    const versions = new Map();
    p.versions.forEach((v, vi) => {
      exact(v, ['version','dependencies'], 'packages['+pi+'].versions['+vi+']');
      const ver = int(v.version, 'version');
      if (versions.has(ver)) throw Error('duplicate version in package ' + n);
      if (!Array.isArray(v.dependencies)) throw Error('dependencies must be an array');
      const deps = [];
      const seen = new Set();
      v.dependencies.forEach((d, di) => {
        const q = range(d, 'dependency '+n+'@'+ver+'['+di+']');
        if (seen.has(q.name)) throw Error('duplicate dependency name in '+n+'@'+ver);
        seen.add(q.name); deps.push(q);
      });
      versions.set(ver, {version:ver, dependencies:deps});
    });
    packages.set(n, {name:n, versions});
  });
  const roots = []; const seen = new Set();
  raw.roots.forEach((r,i) => {
    const q = range(r, 'roots['+i+']');
    if (seen.has(q.name)) throw Error('duplicate root name: ' + q.name);
    seen.add(q.name); roots.push(q);
  });
  return {packages, roots};
}
function solve(model) {
  const names = [...model.packages.keys()].sort();
  let best = null;
  function better(a,b) {
    if (!b) return true;
    for (const n of names) {
      const av = a.has(n) ? a.get(n) : 0, bv = b.has(n) ? b.get(n) : 0;
      if (av !== bv) return av > bv;
    }
    return false;
  }
  function search(assign, constraints) {
    for (const [n, rs] of constraints) {
      const p = model.packages.get(n);
      if (!p) return;
      if (assign.has(n)) {
        const v = assign.get(n);
        if (!rs.every(r => v >= r.min && v <= r.max)) return;
      }
    }
    let choice = null, candidates = null;
    for (const [n, rs] of constraints) if (!assign.has(n)) {
      const p = model.packages.get(n);
      if (!p) return;
      const cs = [...p.versions.values()].filter(v => rs.every(r=>v.version>=r.min && v.version<=r.max))
        .sort((a,b)=>b.version-a.version);
      if (!cs.length) return;
      if (!candidates || cs.length < candidates.length || (cs.length === candidates.length && n < choice)) {
        choice=n; candidates=cs;
      }
    }
    if (!choice) {
      if (better(assign,best)) best = new Map(assign);
      return;
    }
    for (const v of candidates) {
      const next = new Map(assign); next.set(choice,v.version);
      const nc = new Map();
      for (const [n,rs] of constraints) nc.set(n,rs.slice());
      let okay = true;
      for (const d of model.packages.get(choice).versions.get(v.version).dependencies) {
        if (!model.packages.has(d.name)) { okay=false; break; }
        const arr = nc.get(d.name) || []; arr.push(d); nc.set(d.name,arr);
      }
      if (okay) search(next,nc);
    }
  }
  if (model.roots.length === 0) return [];
  const initial = new Map();
  for (const r of model.roots) initial.set(r.name, [r]);
  search(new Map(), initial);
  if (!best) throw Error('no satisfiable resolution');
  return [...best.keys()].sort().map(n=>({name:n,version:best.get(n)}));
