function collision(input, output) {
  const ip = path.resolve(input), op = path.resolve(output);
  if (ip === op) return true;
  let ir, or;
  try { ir = fs.realpathSync.native(ip); } catch (_) { ir = ip; }
  try { or = fs.realpathSync.native(op); } catch (_) { or = op; }
  if (ir === or) return true;
  try {
    const a=fs.statSync(ip), b=fs.statSync(op);
    if (a.dev === b.dev && a.ino === b.ino) return true;
  } catch (_) {}
