    fail(usage().trim(),1); return;
  }
  const input=argv[1], output=argv[3];
  try {
    if (collision(input,output)) throw Error('input and output identity collision');
    const text=fs.readFileSync(input,'utf8');
    let raw; try { raw=JSON.parse(text); } catch (_) { throw Error('input is not valid JSON'); }
    const model=validate(raw), result=solve(model);
    const out=JSON.stringify({packages:result})+'\n';
    const dir=path.dirname(path.resolve(output)), base=path.basename(output);
    const tmp=path.join(dir,'.'+base+'.tmp-'+process.pid+'-'+Date.now());
    let fd;
    try { fd=fs.openSync(tmp, fs.constants.O_WRONLY|fs.constants.O_CREAT|fs.constants.O_EXCL, 0o600);
      fs.writeFileSync(fd,out,'utf8'); fs.fsyncSync(fd); fs.closeSync(fd); fd=null;
      fs.renameSync(tmp,output);
    } finally { if (fd !== undefined && fd !== null) try { fs.closeSync(fd); } catch (_) {}
      try { if (fs.existsSync(tmp)) fs.unlinkSync(tmp); } catch (_) {} }
  } catch (e) {
    const code = e && e.message === 'no satisfiable resolution' ? 2 : 1;
    fail(e && e.message ? e.message : String(e), code);
  }
}
main(process.argv.slice(2));

