'use strict';

const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const cp = require('node:child_process');

const root = __dirname;
const cli = path.join(root, 'resolve.js');
const fixture = path.join(root, 'fixtures', 'impossible-cycle.json');
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'resolver-impossible-cycle-'));

function exhaustive(catalogue) {
  const byName = new Map(catalogue.packages.map((p) => [p.name, p]));
  const names = catalogue.packages.map((p) => p.name).sort();
  let satisfiable = false;

  function visit(index, chosen) {
    if (satisfiable) return;
    if (index < names.length) {
      for (const version of byName.get(names[index]).versions) {
        chosen.set(names[index], version);
        visit(index + 1, chosen);
        chosen.delete(names[index]);
      }
      return;
    }
    for (const root of catalogue.roots) {
      const selected = chosen.get(root.name);
      if (!selected || selected.version < root.min || selected.version > root.max) return;
    }
    for (const selected of chosen.values()) {
      for (const dependency of selected.dependencies) {
        const target = chosen.get(dependency.name);
        if (!target || target.version < dependency.min || target.version > dependency.max) return;
      }
    }
    satisfiable = true;
  }

  visit(0, new Map());
  return satisfiable;
}

function run(catalogue, label) {
  const input = path.join(tmp, label + '.json');
  const output = path.join(tmp, label + '.lock.json');
  const inputBytes = Buffer.from(JSON.stringify(catalogue) + '\n');
  const originalOutput = Buffer.from('do-not-replace\n');
  fs.writeFileSync(input, inputBytes);
  fs.writeFileSync(output, originalOutput);

  const started = Date.now();
  const result = cp.spawnSync(process.execPath, [
    cli, '--input', input, '--out', output
  ], {encoding: 'utf8', timeout: 1500});
  assert.equal(result.error, undefined, label + ': subprocess failed to start');
  assert.equal(result.status, 2, label + ': expected unsatisfiable exit');
  assert.ok(Date.now() - started < 1500, label + ': did not terminate');
  assert.equal(result.stdout, '', label + ': refusal must not write stdout diagnostics');
  assert.match(result.stderr, /resolve: no satisfiable resolution/, label + ': missing stderr diagnostic');
  assert.deepEqual(fs.readFileSync(output), originalOutput, label + ': output was changed');
  assert.deepEqual(fs.readFileSync(input), inputBytes, label + ': input was changed');
}

const fixed = JSON.parse(fs.readFileSync(fixture, 'utf8'));
assert.equal(exhaustive(fixed), false, 'independent oracle expected the fixed cycle to be unsatisfiable');
run(fixed, 'fixed-impossible-cycle');

function generatedCycle(id, aRange, bRange) {
  return {
    packages: [
      {name: 'A' + id, versions: [1, 2].map((version) => ({
        version,
        dependencies: version === 1
          ? [{name: 'B' + id, min: bRange[0], max: bRange[1]}]
          : []
      }))},
      {name: 'B' + id, versions: [1, 2].map((version) => ({
        version,
        dependencies: version === 1
          ? [{name: 'A' + id, min: aRange[0], max: aRange[1]}]
          : []
      }))}
    ],
    roots: [{name: 'A' + id, min: 1, max: 1}]
  };
}

const generated = [
  generatedCycle('zero', [2, 2], [1, 1]),
  generatedCycle('one', [2, 2], [1, 1]),
  generatedCycle('two', [2, 2], [1, 1])
];
for (const [index, catalogue] of generated.entries()) {
  assert.equal(exhaustive(catalogue), false, 'generated oracle case must be unsatisfiable');
  run(catalogue, 'generated-impossible-cycle-' + index);
}

console.log('impossible-cycle subprocess tests passed');

